@bp.route("/suggest/respond/<int:msg_id>", methods=["POST"])
@login_required
def respond_suggestion(msg_id):
    msg = db.get_or_404(Message, msg_id)
    if msg.receiver_id != current_user.id:
        return jsonify({"error": t("route.suggestion_not_yours")}), 403
    if msg.message_type not in ("suggestion_meal", "suggestion_workout"):
        return jsonify({"error": t("route.not_suggestion")}), 400

    data = request.get_json(silent=True) or {}
    action = data.get("action")
    if action not in ("accept", "decline"):
        return jsonify({"error": t("route.invalid_action")}), 400

    # Öğün mü antrenman mı kararını ORİJİNAL tipten ver — aşağıda message_type'a
    # "_accepted"/"_declined" eklendikten sonra substring kontrolü mantığı mutasyona
    # bağlardı (B7).
    is_meal = msg.message_type == "suggestion_meal"
    nutrients = None
    if action == "accept":
        msg.message_type = msg.message_type + "_accepted"
        reply = Message(sender_id=current_user.id, receiver_id=msg.sender_id,
                        body=f"✅ Önerini kabul ettim: {msg.body[:100]}",
                        message_type="text")
        db.session.add(reply)

        if is_meal:
            nutrients = _process_meal_suggestion_accept(msg)
    else:
        msg.message_type = msg.message_type + "_declined"

    db.session.commit()

    resp = {"message": t("route.accepted") if action == "accept" else t("route.declined"),
            "new_type": msg.message_type}
    if action == "accept" and nutrients:
        resp["nutrients"] = nutrients
        resp["message"] = t("route.accepted_kcal", kcal=int(nutrients['kalori']))
    elif action == "accept" and is_meal and nutrients is None:
        # Öneri kabul edildi ama makrolar hesaplanamadı → öğün GÜNLÜĞE EKLENMEDI
        # (sıfır-makro satırı yazılmaz). Kullanıcıya sessiz başarı yerine durumu bildir.
        resp["message"] = t("route.accepted_no_calc")
    return jsonify(resp)


def _process_meal_suggestion_accept(msg):
    sender = db.session.get(User, msg.sender_id)
    sender_name = sender.full_name or sender.username if sender else "Arkadaş"
    suffix = _turkish_ablative_suffix(sender_name)
    ogun_title = f"{sender_name}{suffix} alınan öneri"

    items = _parse_suggestion_items(msg.body)
    if not items:
        # Gövde öğelere ayrıştırılamadı: kanonik MealLog defterine SIFIR-makro satırı
        # YAZMA — kalıcı sıfır satırı günlük toplamları, protein nudge'ını ve haftalık
        # raporları sessizce bozar (meallog.py'deki aynı koruma). Yalnızca metadata logla.
        current_app.logger.warning(
            "[SUGGESTION] Öneri gövdesi ayrıştırılamadı (msg=%s, len=%s) — öğün loglanmadı.",
            msg.id, len(msg.body or ""))
        return None

    total = {"calories": 0, "protein": 0, "carbs": 0, "fat": 0}
    try:
        cached_hits, uncached = _get_cached_macros(items, basis="per_serving")
        macro_map = dict(cached_hits)
        per_100g_items = {}

        if uncached:
            try:
                token = _get_fatsecret_token()
                per_serving, per_100g_items = _lookup_macros_fatsecret(uncached, token)
                macro_map.update(per_serving)
            except Exception as e:
                current_app.logger.warning("[SUGGESTION] FatSecret başarısız, LLM yedeğine düşülüyor: %s", type(e).__name__)

            if per_100g_items:
                weights = _estimate_serving_weights_llm(list(per_100g_items.keys()))
                for name, base in per_100g_items.items():
                    scale = weights.get(name, 150.0) / 100.0
                    macro_map[name] = {
                        "calories": round(base["calories"] * scale, 1),
                        "protein": round(base["protein"] * scale, 1),
                        "carbs": round(base["carbs"] * scale, 1),
                        "fat": round(base["fat"] * scale, 1),
                    }

            missing = [n for n in uncached if n not in macro_map]
            if missing:
                llm_macros = _estimate_macros_llm(missing)
                macro_map.update(llm_macros)

            _cache_macros(macro_map, basis="per_serving")

        for item in items:
            m = macro_map.get(item, {})
            total["calories"] += m.get("calories", 0)
            total["protein"] += m.get("protein", 0)
            total["carbs"] += m.get("carbs", 0)
            total["fat"] += m.get("fat", 0)

    except Exception as e:
        current_app.logger.warning("[SUGGESTION] Makro hattı hatası: %s", type(e).__name__)
        try:
            llm_macros = _estimate_macros_llm(items)
            for item in items:
                m = llm_macros.get(item, {})
                total["calories"] += m.get("calories", 0)
                total["protein"] += m.get("protein", 0)
                total["carbs"] += m.get("carbs", 0)
                total["fat"] += m.get("fat", 0)
        except Exception:
            pass

    # Parse/lookup/LLM hepsi başarısız olup toplam tümüyle sıfır kaldıysa kanonik
    # deftere SIFIR-makro satırı YAZMA (yukarıdaki ayrıştırma-hatası ile aynı gerekçe).
    if total["calories"] <= 0 and total["protein"] <= 0 and total["carbs"] <= 0 and total["fat"] <= 0:
        current_app.logger.warning(
            "[SUGGESTION] Makrolar hesaplanamadı (msg=%s, %s öğe) — öğün loglanmadı.",
            msg.id, len(items))
        return None

    entry = MealLog(
        user_id=current_user.id, ogun=ogun_title,
        yemekler=", ".join(items),
        kalori=round(total["calories"], 1),
        protein=round(total["protein"], 1),
        karb=round(total["carbs"], 1),
        yag=round(total["fat"], 1),
        tarih=day_key()
    )
    db.session.add(entry)
    current_app.logger.info("[SUGGESTION] Öğün loglandı (msg=%s) → %.0f kcal", msg.id, total["calories"])
    return {"kalori": entry.kalori, "protein": entry.protein, "karb": entry.karb, "yag": entry.yag}
